window.MORE=(window.MORE||[]).concat([
{id:"penguin",t:"Penguins",c:"Animals and Nature",i:"🐧",p:[["Flightless swimmers","Penguins are flightless seabirds that use their flippers to swim. About 18 species live almost entirely in the Southern Hemisphere, from Antarctica to the Galápagos Islands."],["Emperor penguins","Emperors stand about 1.1 m tall. After the female lays one egg, the male balances it on his feet through the Antarctic winter while she feeds at sea."],["Warm in the cold","Dense, waterproof feathers and a layer of fat insulate them, and birds huddle together in groups to share warmth."]],r:["antarc","eco"]},
{id:"octopus",t:"Octopuses",c:"Animals and Nature",i:"🐙",p:[["Body","An octopus has eight arms, three hearts and blue, copper-based blood. It has no bones, so it can squeeze through tiny gaps."],["Intelligence","Octopuses solve puzzles, open jars and use tools such as coconut shells for shelter."],["Camouflage","Special skin cells let them change color and texture within moments to hide or signal. Most live only a few years."]],r:["pacific","reef"]},
{id:"wolf",t:"Wolves",c:"Animals and Nature",i:"🐺",p:[["Pack life","Gray wolves live in packs, usually a family led by a breeding pair, and hunt together to bring down large prey such as elk and deer."],["Dogs","Domestic dogs descend from wolves, in a process of domestication that began at least 15,000 years ago."],["Return","Wolves were reintroduced to Yellowstone National Park in 1995, and many ecologists credit them with helping the park’s ecosystem recover."]],r:["eco","evo"]},
{id:"frog",t:"Frogs and Amphibians",c:"Animals and Nature",i:"🐸",p:[["Two lives","Amphibians such as frogs, toads and salamanders typically start life in water and, as adults, live partly on land. A frog begins as an egg, then a tadpole that grows legs."],["Skin","They breathe partly through thin, moist skin, which also makes them sensitive to pollution."],["Decline","Roughly 7,000 species of frogs and toads exist, and a fungal disease called chytridiomycosis, together with habitat loss, has caused serious declines."]],r:["eco","amazon"]},
{id:"tiger",t:"Tigers",c:"Animals and Nature",i:"🐅",p:[["Biggest cat","The tiger is the largest cat, and big male Siberian tigers can weigh around 250 kg or more. No two tigers have the same stripes."],["Range","Tigers once ranged across much of Asia but now survive in a small fraction of that area. India holds the largest number of wild tigers."],["Recovery","Wild tiger numbers fell to a low point in the early 2000s, and protection of reserves has helped some populations to grow again."]],r:["eco","phbio"]},
{id:"bat",t:"Bats",c:"Animals and Nature",i:"🦇",p:[["Flying mammals","Bats are the only mammals capable of true flight, and more than 1,400 species are known."],["Echolocation","Many bats find insects in the dark by calling out and listening to the echoes."],["Helpers","Bats eat vast numbers of insects, and fruit-eating species pollinate flowers and spread seeds, including bananas, mangoes and the baobab trees of Africa."]],r:["insect","phbio"]},
{id:"jupiter",t:"Jupiter",c:"Space and Astronomy",i:"🟠",p:[["Giant planet","Jupiter is about eleven times wider than Earth and has more than twice the mass of all the other planets combined. It is made mostly of hydrogen and helium."],["Moons","Galileo found the four large moons, Io, Europa, Ganymede and Callisto, in 1610. Ganymede is the biggest moon in the Solar System and is larger than Mercury."],["Missions","The Great Red Spot is a storm that has lasted for centuries. NASA’s Juno spacecraft has orbited Jupiter since July 2016."]],r:["solar","scope"]},
{id:"saturn",t:"Saturn",c:"Space and Astronomy",i:"🪐",p:[["Rings","Saturn’s rings are made mostly of water ice, from dust grains to boulders. They span hundreds of thousands of kilometers but are often only about 10 m thick."],["Titan","Saturn’s moon Titan has a thick atmosphere and lakes of liquid methane and ethane."],["Cassini","The Cassini–Huygens mission arrived in 2004, the Huygens probe landed on Titan in January 2005, and Cassini ended its mission in 2017 by plunging into Saturn."]],r:["solar","space"]},
{id:"milky",t:"The Milky Way",c:"Space and Astronomy",i:"🌌",p:[["Our galaxy","The Milky Way is a barred spiral galaxy about 100,000 light-years across, containing hundreds of billions of stars."],["Our place","The Sun lies roughly 26,000 light-years from the center and takes about 225 to 250 million years to orbit it."],["Center and future","A supermassive black hole, Sagittarius A*, sits at the center. In several billion years the Milky Way is expected to collide and merge with the Andromeda Galaxy."]],r:["stars","bh"]},
{id:"iss",t:"The International Space Station",c:"Space and Astronomy",i:"🛰️",p:[["Building it","Assembly began in 1998 with the launch of the Zarya module, and the station has been continuously occupied since November 2000."],["Orbit","It circles Earth about every 90 minutes at roughly 400 km up, at around 7.7 km/s, which means 16 sunrises a day for its crew."],["Partners","It is a partnership of the United States, Russia, Europe, Japan and Canada, and is about the size of a football field."]],r:["space","sat"]},
{id:"eclipse",t:"Eclipses",c:"Space and Astronomy",i:"🌑",p:[["Solar eclipses","In a solar eclipse the Moon passes between the Sun and Earth. The path of total darkness is narrow, and a total eclipse is visible from any given spot only about once every few hundred years."],["Lunar eclipses","In a lunar eclipse Earth’s shadow falls on the Moon, which often glows a dim red."],["Recent eclipses","A total solar eclipse crossed Greenland, Iceland and Spain on 12 August 2026."]],r:["moon","solar"]},
{id:"pulsar",t:"Neutron Stars and Pulsars",c:"Space and Astronomy",i:"💫",p:[["Dense stars","A neutron star is the collapsed core of a massive star, only about 20 km across yet heavier than the Sun. A teaspoon of its material would weigh about a billion metric tons."],["Pulsars","Some neutron stars spin rapidly and sweep beams of radio waves across space like a lighthouse. Jocelyn Bell Burnell discovered the first pulsar in 1967."],["Collisions","In 2017 detectors recorded gravitational waves from two neutron stars merging, and telescopes also saw light from the blast."]],r:["stars","relat"]},
{id:"supdem",t:"Supply and Demand",c:"Economics and Society",i:"⚖️",p:[["The idea","When more people want a good than there is supply of it, its price tends to rise, and when supply exceeds demand, the price tends to fall."],["Adam Smith","Adam Smith described how markets coordinate buyers and sellers in The Wealth of Nations, published in 1776."],["Real-time markets","In electricity markets prices can change within minutes, because supply and demand have to match at every moment."]],r:["phecon","indrev"]},
{id:"money",t:"Money and Banking",c:"Economics and Society",i:"🪙",p:[["What money does","Money works as a medium of exchange, a store of value and a unit of account."],["History","The first coins were minted in Lydia, in present-day Turkey, around 600 BCE, and paper money appeared in China in the Song dynasty."],["Central banks","The Bank of England was founded in 1694, and central banks today manage money supply and interest rates to keep prices stable."]],r:["china","phecon"]},
{id:"trade",t:"Trade and Globalization",c:"Economics and Society",i:"🚢",p:[["Why trade","David Ricardo’s 1817 theory of comparative advantage says that countries gain by specializing in what they produce relatively best, even when one is better at everything."],["Containers","Container shipping began in 1956 and sharply cut the cost of moving goods. The General Agreement on Tariffs and Trade of 1947 became the World Trade Organization in 1995."],["World trade","Trade in goods and services is worth more than 30 trillion US dollars a year, and China, the United States and Germany are the largest traders."]],r:["silk","phecon"]},
{id:"rice",t:"Rice",c:"Food and Agriculture",i:"🍚",p:[["Staple crop","Rice is the main food for about half of humanity, and Asia produces the vast majority of the world’s rice."],["Origins","Rice was domesticated in the Yangtze River region of China roughly 9,000 years ago, and terraced paddies later spread across Asia."],["Research","The International Rice Research Institute, founded in 1960 with support from the Ford and Rockefeller foundations, released the high-yield variety IR8 in 1966, part of the Green Revolution."]],r:["banaue","agri"]},
{id:"agri",t:"The Agricultural Revolution",c:"Food and Agriculture",i:"🌾",p:[["Beginnings","Around 10,000 years ago people in the Fertile Crescent began farming wheat and barley and herding sheep and goats. Farming arose independently in China, Mesoamerica and other regions."],["Consequences","Farming created food surpluses, which supported dense villages, cities, specialized jobs and eventually states."],["Green Revolution","In the 1960s Norman Borlaug and others developed high-yield crops, and Borlaug won the Nobel Peace Prize in 1970."]],r:["mesop","egypt"]},
{id:"coffee",t:"Coffee and Tea",c:"Food and Agriculture",i:"☕",p:[["Coffee","Legend credits an Ethiopian goat herder named Kaldi with discovering coffee. It spread through Yemen and the Ottoman Empire, and coffeehouses became places of conversation."],["Species","Arabica is the most widely grown coffee, followed by robusta. Liberica and excelsa are two rarer species."],["Tea","Tea came from China and is, after water, the most consumed drink in the world."]],r:["ottoman","china"]}]);
