window.MORE=(window.MORE||[]).concat([
{id:"inflation",t:"Inflation",c:"Economics and Society",i:"📈",p:[["Meaning","Inflation is a general rise in prices over time, so each unit of money buys less. Statisticians track it with a consumer price index based on a basket of everyday goods."],["Targets","Many central banks aim for low, steady inflation of about 2%, including the US Federal Reserve, the European Central Bank and the Bank of England, while some emerging economies target a range of a few percent."],["Extremes","In Germany’s hyperinflation of 1923, prices doubled roughly every four days at the peak, and Zimbabwe suffered a similar collapse in 2008."]],r:["money","phecon"]},
{id:"gdp",t:"Gross Domestic Product",c:"Economics and Society",i:"🏦",p:[["Definition","Gross domestic product, or GDP, is the total value of goods and services a country produces in a year. Dividing it by population gives GDP per person."],["History","Simon Kuznets developed the first national income accounts in the United States in the 1930s."],["Limits","GDP leaves out unpaid work such as housework and says nothing about how income is shared or about environmental damage."]],r:["phecon","trade"]},
{id:"stockm",t:"Stock Markets",c:"Economics and Society",i:"💹",p:[["Origins","Shares of the Dutch East India Company began trading in Amsterdam in 1602, which is considered the first stock exchange. The New York Stock Exchange traces its roots to 1792."],["Indexes","Indexes such as the Dow Jones Industrial Average and the S&P 500 track groups of shares. Other major indexes include Japan’s Nikkei 225, Britain’s FTSE 100 and Hong Kong’s Hang Seng."],["Crashes","Prices can fall sharply, as in the crash of October 1929 and on Black Monday, 19 October 1987."]],r:["money","supdem"]},
{id:"insur",t:"Insurance",c:"Economics and Society",i:"☂️",p:[["Idea","Insurance spreads risk: many people pay small premiums, and the few who suffer a loss are paid from the pool."],["Origins","Lloyd’s of London began in a coffee house in the late 1680s, where merchants arranged cover for ships and cargo."],["Math","Actuaries use probability and statistics to estimate risks and set premiums for life, health, property and other cover."]],r:["prob","money"]},
{id:"urban",t:"Cities and Urbanization",c:"Economics and Society",i:"🏙️",p:[["Growth","Since 2007, more than half of the world’s people have lived in cities, and the share continues to rise."],["Megacities","Jakarta is the world’s largest urban area, with about 42 million people, according to a 2025 United Nations report, followed by Dhaka and Tokyo. Cities such as Manila and Mumbai are among the most densely populated on Earth."],["Challenges","Fast-growing cities face housing shortages, traffic, pollution and strained water and power, and good planning and transport help to manage them."]],r:["manila","indrev"]},
{id:"wheat",t:"Wheat and Bread",c:"Food and Agriculture",i:"🥖",p:[["Ancient crop","Wheat was among the first crops farmed, about 10,000 years ago, with early types such as einkorn and emmer. It is grown on more land than any other food crop."],["Bread","Ancient Egyptians used yeast to make leavened bread, and flour milled from wheat is the basis of bread, noodles and pasta."],["Grain trade","China, India, Russia and the United States are major producers, and wheat is traded around the world."]],r:["agri","egypt"]},
{id:"spice",t:"Spices and the Spice Trade",c:"Food and Agriculture",i:"🌶️",p:[["Prized goods","Pepper, cinnamon, cloves and nutmeg were valued in ancient and medieval times for flavor, preserving food and medicine."],["Spice Islands","Cloves and nutmeg grew only on a few islands in Indonesia’s Maluku group, the original Spice Islands."],["Sea routes","Vasco da Gama’s 1498 voyage to India opened a sea route for European traders, and the Dutch East India Company later seized control of much of the trade."]],r:["explor","silk"]},
{id:"choco",t:"Chocolate",c:"Food and Agriculture",i:"🍫",p:[["Mesoamerica","Peoples of Mesoamerica, including the Maya and Aztecs, made cacao into a bitter, frothy drink and used the beans as currency."],["Europe","Spanish traders brought cacao to Europe in the 1500s. J. S. Fry and Sons made the first solid eating chocolate in 1847, and Daniel Peter of Switzerland invented milk chocolate in 1875."],["Today","West Africa, led by Ivory Coast and Ghana, grows roughly 60% of the world’s cocoa."]],r:["aztec","maya"]},
{id:"fish",t:"Fishing and Aquaculture",c:"Food and Agriculture",i:"🐟",p:[["Food from water","Fish and shellfish provide protein for billions of people, especially in Asia."],["Overfishing","About a third of wild fish stocks are fished beyond sustainable limits. Quotas and protected areas help stocks recover."],["Fish farming","Aquaculture now supplies about half of the fish people eat. China farms more fish than all other countries combined, and Norway leads in farmed salmon."]],r:["pacific","reef"]},
{id:"potato",t:"Potatoes",c:"Food and Agriculture",i:"🥔",p:[["Andean origin","Potatoes were domesticated in the Andes roughly 8,000 years ago, and the region still grows thousands of varieties."],["To Europe","They reached Europe in the 1500s and became a staple crop there, and after rice and wheat are one of the world’s most important food crops."],["Irish famine","A blight destroyed Ireland’s potato crops from 1845, and the Great Famine killed about a million people and drove another million to emigrate."]],r:["andes","explor"]}]);
