window.MORE=(window.MORE||[]).concat([
{id:"kidney",t:"The Kidneys",c:"Health and the Body",i:"🫘",p:[["Function","The two fist-sized kidneys filter the blood, removing waste and extra water as urine. Each holds about a million tiny filters called nephrons."],["Balance","They help control blood pressure and keep the body’s salts and fluids in balance."],["Treatment","Dialysis can filter the blood when kidneys fail, and the first successful kidney transplant, between identical twins, took place in Boston in 1954."]],r:["blood","water"]},
{id:"hormone",t:"Hormones",c:"Health and the Body",i:"⚗️",p:[["Messengers","Hormones are chemical messengers released into the blood by glands such as the thyroid, adrenals and pituitary, and they act on distant organs."],["Examples","Insulin controls blood sugar, adrenaline prepares the body for fight or flight and melatonin helps regulate sleep."],["Insulin","Frederick Banting and Charles Best discovered insulin in 1921, and it was first used to treat a patient in 1922."]],r:["sleep","digest"]},
{id:"hygiene",t:"Hygiene and Handwashing",c:"Health and the Body",i:"🧼",p:[["Semmelweis","In 1847 the physician Ignaz Semmelweis showed that doctors washing their hands with a chlorine solution sharply cut deaths in a maternity ward."],["Germ theory","Pasteur and Koch later proved that microbes cause disease, which made handwashing and clean water central to public health."],["Today","Health agencies advise washing hands with soap for at least 20 seconds, and Global Handwashing Day is observed on 15 October."]],r:["microbe","vacc"]},
{id:"malaria",t:"Malaria",c:"Health and the Body",i:"🦟",p:[["Cause","Malaria is caused by Plasmodium parasites spread by the bites of Anopheles mosquitoes. Ronald Ross showed the mosquito’s role in 1897."],["Burden","It kills roughly 600,000 people a year, most of them young children in Africa."],["Prevention","Bed nets, insecticides and drugs help prevent it, and the World Health Organization recommended its first malaria vaccine in 2021."]],r:["microbe","vacc"]},
{id:"allergy",t:"Allergies",c:"Health and the Body",i:"🌼",p:[["What they are","An allergy happens when the immune system overreacts to a harmless substance such as pollen, dust mites or certain foods."],["Symptoms","The body releases histamine, which causes sneezing, itching and swelling. Antihistamines ease mild symptoms."],["Anaphylaxis","A severe reaction called anaphylaxis is a medical emergency that is treated with an injection of epinephrine."]],r:["immune","skin"]},
{id:"spine",t:"The Spine and Posture",c:"Health and the Body",i:"🦴",p:[["Structure","The spine is made of 33 vertebrae, with cushioning discs between most of them. It protects the spinal cord, the bundle of nerves that links the brain to the body."],["Curves","The spine has natural curves that absorb shock and keep the body balanced."],["Care","Regular movement, strong core muscles and good posture while sitting and lifting help prevent back pain."]],r:["bones","brain"]},
{id:"michel",t:"Michelangelo",c:"Arts and Literature",i:"🗿",p:[["Life","Michelangelo Buonarroti lived from 1475 to 1564 and worked as a sculptor, painter, architect and poet."],["Sculpture","He carved the marble David in Florence between 1501 and 1504 and the Pietà in Rome."],["Painting","He painted the Sistine Chapel ceiling between 1508 and 1512 and the Last Judgment in 1536 to 1541, and designed the dome of St. Peter’s Basilica."]],r:["renais","davinci"]},
{id:"vangogh",t:"Vincent van Gogh",c:"Arts and Literature",i:"🌻",p:[["Life","Van Gogh was born in the Netherlands in 1853 and died in France in 1890. He sold very few paintings in his lifetime."],["Style","His bold colors and swirling brushwork appear in The Starry Night, which he painted in 1889 while staying at an asylum in Saint-Rémy."],["Letters","His letters to his brother Theo, who supported him, describe his work and ideas and are widely read."]],r:["impress","renais"]},
{id:"picasso",t:"Pablo Picasso",c:"Arts and Literature",i:"🖌️",p:[["Life","Picasso, born in Spain in 1881, lived mostly in France and died in 1973. He worked as a painter, sculptor and printmaker."],["Cubism","With Georges Braque he developed Cubism, which showed subjects from several angles at once, and Les Demoiselles d’Avignon of 1907 was a turning point."],["Guernica","His huge painting Guernica, made in 1937, responded to the bombing of the Basque town of Guernica during the Spanish Civil War."]],r:["impress","vangogh"]},
{id:"fairy",t:"Fairy Tales",c:"Arts and Literature",i:"🧚",p:[["Oral roots","Fairy tales grew out of stories told aloud for centuries, in which magic and ordinary life mix."],["Collectors","Charles Perrault published tales such as Cinderella in 1697, the Brothers Grimm published their first collection in 1812 and Hans Christian Andersen wrote original tales from the 1830s."],["Worldwide","Every culture has such stories, from the Arabian Nights to the folktales of Africa, Asia and the Americas."]],r:["phfolk","novel"]},
{id:"anim",t:"Animation",c:"Arts and Literature",i:"🎞️",p:[["Early days","Animation creates the illusion of movement from a series of drawn images. Émile Cohl made one of the earliest animated films, Fantasmagorie, in 1908."],["Feature films","Disney’s Snow White and the Seven Dwarfs (1937) was the first full-length cel animated feature, and Toy Story (1995) was the first fully computer-animated one."],["Around the world","Studio Ghibli, founded in 1985, brought Japanese animation to a global audience, and studios everywhere now make animated films."]],r:["cinema","camera"]},
{id:"ballet",t:"Ballet",c:"Arts and Literature",i:"🩰",p:[["Origins","Ballet began in the courts of the Italian Renaissance and developed in France, where Louis XIV founded the Royal Academy of Dance in 1661."],["Technique","Dancers train for years in positions and steps that have French names, and dancing on the tips of the toes, called pointe, became common in the 1800s."],["Classics","Tchaikovsky’s Swan Lake (1877) and The Nutcracker (1892) are among the most performed ballets in the world."]],r:["musicw","theatre"]}]);
